<?php
session_start();include('dbstring.php');include('check-login.php');include_once('class-teacher-utils.php');include_once('administration-ops-utils.php');ensure_class_teacher_table($con);administration_ops_ensure_tables($con);
if(!(isset($_SESSION['ACCESSLEVEL'],$_SESSION['SYSTEMTYPE']) && $_SESSION['ACCESSLEVEL']==='user' && $_SESSION['SYSTEMTYPE']==='Teacher')){header('location:index.php');exit();}$teacherId=$_SESSION['USERID'];if(!class_teacher_has_any_assignment($con,$teacherId)){header('location:teacher-page.php');exit();}
$teacherEsc=mysqli_real_escape_string($con,$teacherId);$students=[];$studentRes=mysqli_query($con,"SELECT DISTINCT su.userid,CONCAT_WS(' ',su.firstname,su.othernames,su.surname) name FROM tbltermregistry tr INNER JOIN tblclassteacher ct ON ct.classid=tr.class_entryid AND ct.batchid=tr.batchid AND ct.termname=tr.termname AND ct.status='active' INNER JOIN tblsystemuser su ON su.userid=tr.userid WHERE ct.userid='$teacherEsc' AND su.systemtype='Student' AND su.status='active' ORDER BY su.firstname,su.surname");if($studentRes)while($row=mysqli_fetch_assoc($studentRes))$students[]=$row;
$message='';if(isset($_POST['report_case'])){$student=trim((string)($_POST['studentid']??''));$category=trim((string)($_POST['category']??''));$date=trim((string)($_POST['incidentdate']??''));$summary=trim((string)($_POST['summary']??''));$valid=false;foreach($students as $item){if($item['userid']===$student){$valid=true;break;}}if($valid&&$category!==''&&$date!==''&&$summary!==''){$id=administration_ops_id('WEL');$status='open';$action='Reported by class teacher; awaiting Administration review.';$parent=0;$follow=null;$stmt=mysqli_prepare($con,'INSERT INTO tblstudentwelfarecase(caseid,studentid,category,incidentdate,summary,actiontaken,parentcontacted,followupdate,status,recordedby) VALUES(?,?,?,?,?,?,?,?,?,?)');mysqli_stmt_bind_param($stmt,'ssssssisss',$id,$student,$category,$date,$summary,$action,$parent,$follow,$status,$teacherId);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$message='Your welfare concern has been sent to the Assistant Headmaster Administration.';}else{$message='Please complete the form and select a student from your assigned class.';}}
?>
<!doctype html><html><head><?php include('title.php');include('links.php');?><link rel="stylesheet" href="css/headmaster-dashboard.css"><link rel="stylesheet" href="css/assistant-admin-ops.css"></head><body class="hm-page aops-page"><div class="header"><?php include('menu.php');?></div><main class="hm-shell"><aside class="hm-sidebar"><div class="hm-sidebar__inner"><?php include('welcome.php');include('menuboard.php');?></div></aside><section class="hm-main"><section class="hm-hero hm-hero--single aops-hero"><div><span class="hm-kicker">Class teacher referral</span><h1>Report a student welfare concern</h1><p>Send a factual concern to the Assistant Headmaster Administration for support, safeguarding, discipline, or welfare follow-up.</p><div class="hm-hero__footer"><div class="hm-context"><span><i class="fa fa-user"></i> Class teacher report</span><span><i class="fa fa-lock"></i> Staff-only record</span></div><a class="aops-back" href="teacher-page.php"><i class="fa fa-arrow-left"></i> Teacher dashboard</a></div></div></section><?php if($message!==''){?><div class="aops-flash"><?php echo administration_ops_escape($message);?></div><?php }?><section class="aops-panel" style="max-width:760px"><div class="hm-panel__head"><div><span class="hm-section__eyebrow">New referral</span><h2>Share the concern clearly</h2><p>Use objective facts. The Administration team will record the next action and follow-up.</p></div></div><form method="post" class="aops-form"><label>Student<select name="studentid" required><option value="">Select a student from your assigned class</option><?php foreach($students as $student){?><option value="<?php echo administration_ops_escape($student['userid']);?>"><?php echo administration_ops_escape($student['name']);?></option><?php }?></select></label><div class="aops-inline"><label>Concern type<select name="category" required><option value="">Select</option><option>Discipline</option><option>Health</option><option>Attendance</option><option>Counselling</option><option>Bullying / Safety</option><option>Family / Welfare</option></select></label><label>Date observed<input type="date" name="incidentdate" value="<?php echo date('Y-m-d');?>" required></label></div><label>What happened?<textarea name="summary" required placeholder="State the facts, concern, and any immediate safety need."></textarea></label><button class="aops-button" name="report_case"><i class="fa fa-paper-plane"></i> Send to Administration</button></form></section></section></main></body></html>